package org.eclipse.rdf4j.sail.rdfparser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;

import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.impl.LinkedHashModel;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class ParsedDatasetSourceTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void indexesDistinctNestedTermsWithoutAssertingThem() {
		var inner = VF.createTripleTerm(VF.createIRI("urn:a"), VF.createIRI("urn:b"), VF.createIRI("urn:c"));
		var outer = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), inner);
		var model = new LinkedHashModel();
		model.add(VF.createIRI("urn:r"), VF.createIRI("urn:reifies"), outer);
		model.add(VF.createIRI("urn:r2"), VF.createIRI("urn:reifies"), outer, VF.createIRI("urn:g"));
		var source = new ParsedDatasetSource(model.unmodifiable());
		List<TripleTerm> terms = new ArrayList<>();
		try (var rows = source.getTripleTerms(null, null, null)) {
			while (rows.hasNext()) {
				terms.add(rows.next());
			}
		}
		assertEquals(List.of(outer, inner), terms);
		assertEquals(2, model.size());
		assertFalse(source.hasStatements(outer.getSubject(), outer.getPredicate(), outer.getObject()));
	}

	@Test
	void everyBoundComponentCombinationFiltersAndIsReadOnly() {
		var s = VF.createIRI("urn:s");
		var p = VF.createIRI("urn:p");
		var o = VF.createIRI("urn:o");
		var target = VF.createTripleTerm(s, p, o);
		var model = new LinkedHashModel();
		model.add(s, p, target);
		model.add(s, p, VF.createTripleTerm(VF.createIRI("urn:other"), p, VF.createLiteral("value")));
		var source = new ParsedDatasetSource(model.unmodifiable());
		for (int mask = 0; mask < 8; mask++) {
			var subject = (mask & 1) == 0 ? null : s;
			var predicate = (mask & 2) == 0 ? null : p;
			var object = (mask & 4) == 0 ? null : o;
			try (var rows = source.getTripleTerms(subject, predicate, object)) {
				assertEquals(target, rows.next());
				assertThrows(UnsupportedOperationException.class, rows::remove);
				assertEquals(mask == 0 || mask == 2, rows.hasNext());
			}
		}
		try (var rows = source.getTripleTerms(null, VF.createIRI("urn:missing"), null)) {
			assertFalse(rows.hasNext());
		}
	}

	@Test
	void lazyIndexCanBeReadConcurrently() throws Exception {
		var target = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"));
		var model = new LinkedHashModel();
		model.add(VF.createIRI("urn:r"), VF.createIRI("urn:reifies"), target);
		var source = new ParsedDatasetSource(model.unmodifiable());
		try (var executor = Executors.newFixedThreadPool(4)) {
			Callable<TripleTerm> lookup = () -> {
				try (var rows = source.getTripleTerms(target.getSubject(), null, null)) {
					TripleTerm result = rows.next();
					assertFalse(rows.hasNext());
					return result;
				}
			};
			for (var result : executor.invokeAll(java.util.Collections.nCopies(32, lookup))) {
				assertEquals(target, result.get());
			}
		}
	}
}
